const sqlite3 = require('sqlite3').verbose();

const taskDescrizione = $input.first().json.task_descrizione || '';

if (!taskDescrizione) {
  return [{ json: { output: 'Parametro task_descrizione mancante.' } }];
}

const tasks = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.all(
    `SELECT id, descrizione FROM task 
     WHERE stato = 'aperto' 
     AND LOWER(descrizione) LIKE LOWER(?)
     ORDER BY creato_il DESC LIMIT 5`,
    [`%${taskDescrizione}%`],
    function(err, rows) {
      db.close();
      if (err) reject(err);
      else resolve(rows);
    }
  );
});

if (tasks.length === 0) {
  return [{ json: { output: `Nessun task aperto trovato con descrizione simile a "${taskDescrizione}".` } }];
}

const task = tasks[0];
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const nowISO = now.toISOString().slice(0, 19).replace('T', ' ');

await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.run(
    `UPDATE task SET stato = 'completato', completato_il = ?, updated_at = ? WHERE id = ?`,
    [nowISO, nowISO, task.id],
    function(err) {
      db.close();
      if (err) reject(err);
      else resolve();
    }
  );
});

return [{ json: { 
  output: `Task ID ${task.id} completato: "${task.descrizione}".`
} }];
